"""Complete explicit byte/word layout group and test ONLY new candidates.
Also applies the improved unknown-IV harness to clear firmware metadata.
Does not modify earlier results or device/card files.
"""
from pathlib import Path
import json, time, collections
import eeprom_keyhunt_20261101 as E
import key_research_20261101 as K
ROOT=Path(__file__).resolve().parent
OUT=ROOT/'analysis/eeprom_keyhunt_20261101'

def swap16(b):return b''.join(b[i:i+2][::-1] for i in range(0,len(b),2))
def layouts(b):
    # Group generated by swapping bytes in u16, reversing bytes in u32,
    # and reversing the whole byte string; all widths are multiples of 4.
    for s,first in [('identity',b),('swap16',swap16(b))]:
        for w,second in [('identity',first),('reverse-u32',K.word_reverse(first))]:
            yield s+'|'+w,second
            yield s+'|'+w+'|reverse-all',second[::-1]

def main():
    begun=time.monotonic()
    prior=json.loads((OUT/'eeprom_direct_key_results.json').read_text(encoding='utf-8'))
    boundary=json.loads((OUT/'counter_boundary_selftests.json').read_text(encoding='utf-8'))
    assert boundary['all_passed'] and not prior['key_recovered']
    inventory=json.loads((ROOT/'analysis/sd_card_20261101/inventory_and_eeprom.json').read_text(encoding='utf-8'))
    manifest=json.loads((ROOT/'analysis/verification_20261101/verification.json').read_text(encoding='utf-8'))
    sources=[]
    for e in inventory['eeprom']:
        for v in e['variants']:sources.append((v['file'],v['sha256']))
    for r in inventory['files']:
        if '/PRIVATE/' in r['backup'].replace('\\','/'):sources.append((r['backup'],r['sha256']))
    raw={}
    for i,(name,digest) in enumerate(sources):
        data=(ROOT/name).read_bytes();assert K.sha(data)==digest
        for width in (16,24,32):
            for off in range(len(data)-width+1):raw.setdefault(data[off:off+width],(i,off,width))
    old=set(raw)
    for key in raw:old.add(K.word_reverse(key));old.add(key[::-1])
    assert len(old)==prior['candidate_count'] and K.sha(b''.join(sorted(old)))==prior['candidate_pool_sha256']
    print('PRIOR_POOL_REPRODUCED',len(old),flush=True)
    delta={}
    for key,source in raw.items():
        for label,transformed in layouts(key):
            if transformed not in old:delta.setdefault(transformed,dict(kind='sd-layout-completion',file=sources[source[0]][0],offset=source[1],length=source[2],transform=label))
    del raw
    for name,im in manifest['images'].items():
        data=(ROOT/name).read_bytes();assert K.sha(data)==im['sha256']
        header=data[:im['payload_start']]
        for width in (16,24,32):
            for off in range(len(header)-width+1):
                b=header[off:off+width]
                for label,key in layouts(b):
                    if key not in old:delta.setdefault(key,dict(kind='clear-firmware-metadata-new-harness',file=name,offset=off,length=width,transform=label))
    print('NEW_CANDIDATES',len(delta),flush=True)
    images={n:(ROOT/n).read_bytes() for n in manifest['images']};targets=[]
    for label in ('eep_act_a','eep_act_b','ipu_data','koutei_kao','music'):
        plain=(ROOT/'analysis/william_review/plaintext_samples'/('rec_S5V29_'+label+'_from_G100.bin')).read_bytes()
        for name,im in manifest['images'].items():
            for e in im['partitions']:
                if e['name']==label and e['size']==len(plain) and e['stored_digest']==K.sha(plain) and e['flags']==3:
                    ct=images[name][e['file_offset']:e['end']]
                    targets.append(E.make_target(name,label,plain,ct))
    assert len(targets)==11
    dec,enc=E.prepare(targets);prefix=[];verified=[];ctr_blocks=0
    for index,(key,source) in enumerate(delta.items(),1):
        matches,count=E.screen(key,targets,dec,enc);ctr_blocks+=count
        for i,mode,iv,spec in matches:
            t=targets[i]
            record=dict(image=t['image'],partition=t['partition'],mode=mode,iv=iv.hex() if iv is not None else None,counter_spec=spec,key_hex=key.hex(),source=source)
            prefix.append(record)
            plain=E.decode(key,t['cipher'],mode,iv,spec)
            if plain==t['plain'] and len(plain)==len(t['plain']) and K.sha(plain)==t['sha256']:
                verified.append(dict(**record,full_sha256=K.sha(plain),full_length=len(plain)))
                print('FULL_MATCH',json.dumps(verified[-1]),flush=True)
        if index%50000==0:
            print('DELTA_PROGRESS',index,'/',len(delta),'prefix',len(prefix),'verified',len(verified),'elapsed',round(time.monotonic()-begun,2),flush=True)
    result=dict(scope='Only previously untested keys from explicit layout closure and clear firmware metadata.',
        prior_candidate_count=len(old),prior_pool_reproduced=True,new_candidate_count=len(delta),
        union_candidate_count=len(old)+len(delta),new_pool_sha256=K.sha(b''.join(sorted(delta))),
        counts=dict(targets=len(targets),CBC_pairs=len(delta)*len(targets),ECB_pairs=len(delta)*len(targets),
            OFB_pairs=len(delta)*len(targets),CFB128_pairs=len(delta)*len(targets),
            CTR_spec_hypotheses=len(delta)*len(targets)*len(E.SPECS),CTR_unique_counter_blocks=ctr_blocks),
        prefix_matches=prefix,full_verified_matches=verified,key_recovered=bool(verified),
        candidate_sources=dict(collections.Counter(v['kind'] for v in delta.values())),
        elapsed_seconds=time.monotonic()-begun,
        limitations=['Negative results apply only to direct candidate bytes, this finite layout group, and direct aligned AES hypotheses.',
                     'Same structural/preprocessing/cipher-identification limits as primary experiment.',
                     'Duplicate key values retain one provenance, not all aliases.'])
    for name,digest in sources:assert K.sha((ROOT/name).read_bytes())==digest
    (OUT/'layout_delta_results.json').write_text(json.dumps(result,ensure_ascii=False,indent=2),encoding='utf-8')
    print('FINAL',json.dumps({k:result[k] for k in ['prior_candidate_count','new_candidate_count','union_candidate_count','key_recovered','elapsed_seconds']}),flush=True)
if __name__=='__main__':main()
